import os
from pathlib import Path

# Curated list of common open-source SPDX license identifiers
VALID_SPDX_LICENSES = {
    'MIT', 'Apache-2.0', 'Apache-2.0 WITH LLVMexception',
    'BSD-2-Clause', 'BSD-3-Clause', 'ISC', 'Unlicense',
    'CC0-1.0', 'GPL-3.0-only', 'GPL-3.0-or-later',
    'MPL-2.0', 'Zlib', 'Python-2.0'
}

def extract_license_header(content: str) -> str | None:
    """Extract the SPDX license identifier from a Python file header."""
    lines = content.splitlines()
    for line in lines[:10]:
        line_stripped = line.strip()
        if line_stripped.startswith('#') and 'License' in line_stripped:
            return line_stripped.split('#', 1)[1].strip()
    return None

def validate_spdx_licenses(directory: Path) -> dict[str, list[str]]:
    """Validate SPDX license identifiers in all .py files within a directory."""
    results = {'valid': 0, 'missing_license': 0, 'errors': 0}
    for py_file in sorted(directory.rglob('*.py')):
        try:
            content = py_file.read_text(encoding='utf-8')
            license_id = extract_license_header(content)
            if license_id and license_id in VALID_SPDX_LICENSES:
                results['valid'] += 1
            else:
                results['missing_license'].append(str(py_file))
        except (OSError, UnicodeDecodeError) as exc:
            results['errors'].append((str(py_file), str(exc)))
    return results
```

